function editMeasurement(week){let p=selected(),r=p.history.find(r=>r.week===week);openModal('Изменить измерение',`${plantLabel(p)} · неделя ${week} · ${dateLabel(r.date)}`,`<div class="notice">Изменение появится в черновике. Сохранённая история и текущий прогноз не будут автоматически заменены.</div><table class="entry-table">${metricsFields.map(([k,label])=>`<tr><td>${label}</td><td><input type="number" min="0" step="1" id="edit-${k}" value="${esc(r[k])}" aria-label="${label}"></td></tr>`).join('')}<tr><td><label for="edit-weight">Вес ягоды, г</label></td><td><input type="number" min="0" step="0.1" id="edit-weight" value="${esc(r.weight??'')}" placeholder="—"></td></tr></table><div class="field section-gap"><label for="editNote">Причина изменения</label><input id="editNote" placeholder="Например, уточнение после осмотра"></div>`,'<button class="btn" data-close>Отмена</button><button class="btn primary" id="saveEdit">Добавить исправление</button>');$('saveEdit').onclick=()=>{let d={plant:p.id,week:r.week,date:r.date,edit:true,weight:$('edit-weight').value,editNote:$('editNote').value.trim()};metricsFields.forEach(([k])=>d[k]=$('edit-'+k).value);let err=validateDraft(d,true);if(err){toast(err);return}addDraft(d);closeModal();toast('Исправление добавлено в черновик.')}}
document.addEventListener('click',e=>{let view=e.target.closest('[data-view]');if(view){closeExportMenu();setView(view.dataset.view);return}let a=e.target.closest('[data-action]');if(a){closeExportMenu();action(a.dataset.action);return}if(e.target.closest('[data-close]')){closeModal();return}let b=e.target.closest('[data-measure-tab]');if(b){switchMeasurementTab(b.dataset.measureTab);return}let row=e.target.closest('[data-remove-draft]');if(row){state.drafts.splice(Number(row.dataset.removeDraft),1);renderMeasurements();renderForecast();return}let edit=e.target.closest('[data-edit-week]');if(edit){editMeasurement(Number(edit.dataset.editWeek));return}let pl=e.target.closest('[data-open-plant]');if(pl){let target=DATA.plants.find(p=>p.id===pl.dataset.openPlant);$('cultivar').value=target.cultivar;populatePlants();$('plant').value=target.id;state.selectedVersion=null;state.demoWeek=null;setView(pl.dataset.openView||'forecast');return}let photo=e.target.closest('[data-photo-plant]');if(photo){openPlantPhoto(photo.dataset.photoPlant);return}let camera=e.target.closest('[data-bind-camera-plant]');if(camera){bindPlantCamera(camera.dataset.bindCameraPlant);return}let gallery=e.target.closest('[data-camera-gallery]');if(gallery){showCameraGallery(gallery.dataset.cameraGallery);return}let layout=e.target.closest('[data-registry-layout]');if(layout){state.registryLayout=layout.dataset.registryLayout;renderRegistry();return}let replay=e.target.closest('[data-replay-index]');if(replay){selectForecastReplay(Number(replay.dataset.replayIndex));return}let ver=e.target.closest('[data-version]');if(ver){state.selectedVersion=Number(ver.dataset.version);state.demoWeek=null;closeModal();render();return}let step=e.target.closest('[data-import-step]');if(step){state.importStep=Number(step.dataset.importStep);renderImport();return}if(!e.target.closest('.menu-wrap'))closeExportMenu()});
document.addEventListener('input',e=>{if(e.target.dataset.draft!=null){let d=state.drafts[Number(e.target.dataset.draft)],field=e.target.dataset.field,p=DATA.plants.find(p=>p.id===d.plant);d[field]=e.target.value;if(!p||d.edit)return;if(field==='week'&&Number.isInteger(Number(d.week))&&d.week>=1&&d.week<=18){d.date=dateFor(p,Number(d.week));e.target.closest('tr').querySelector('[data-field="date"]').value=d.date}else if(field==='date'){let week=Object.keys(p.calendar).find(week=>p.calendar[week]===d.date);if(week){d.week=Number(week);e.target.closest('tr').querySelector('[data-field="week"]').value=d.week}}}});
$('season').onchange=populatePlants;$('cultivar').onchange=populatePlants;$('plant').onchange=()=>{clearEntry();state.selectedVersion=null;state.demoWeek=null;state.allWeeks=false;render()};$('entryWeek').onchange=()=>{$('entryDate').value=dateFor(selected(),$('entryWeek').value)};$('weightToggle').onclick=()=>{$('weightField').classList.toggle('hidden');$('weightToggle').textContent=$('weightField').classList.contains('hidden')?'+ Добавить вес ягоды':'− Скрыть вес ягоды'};$('allWeeks').onclick=()=>{state.allWeeks=!state.allWeeks;renderForecast()};$('plantSearch').oninput=renderRegistry;$('cameraFilter').onchange=renderRegistry;$('registryCultivar').onchange=renderRegistry;$('closeModal').onclick=closeModal;$('modalBackdrop').onclick=e=>{if(e.target===$('modalBackdrop'))closeModal()};$('exportButton').onclick=()=>{const open=$('exportMenu').classList.toggle('open');$('exportButton').setAttribute('aria-expanded',String(open));};
$('entryDate').onchange=()=>{let week=Object.keys(selected().calendar).find(week=>dateFor(selected(),week)===$('entryDate').value);if(week){$('entryWeek').value=week;$('entryError').textContent=''}else $('entryError').textContent='Выберите дату еженедельного осмотра из календаря сезона.'};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeExportMenu()}if(e.key==='Tab'&&$('modalBackdrop').classList.contains('open')){let els=[...$('modal').querySelectorAll('button,input,select,textarea,a')].filter(el=>!el.disabled&&el.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
renderMiniInputs();decorate();populatePlants();

function closeExportMenu(){ const menu=$('exportMenu'),button=$('exportButton');const restoreFocus=menu.contains(document.activeElement);menu.classList.remove('open');button.setAttribute('aria-expanded','false');if(restoreFocus)button.focus({preventScroll:true}); }
window.addEventListener('scroll',()=>{if(!matchMedia('(max-width:900px)').matches)closeExportMenu()},{passive:true});
